truncate table public.event_speakers, public.gallery_items, public.events, public.tracks, public.speakers, public.societies, public.sponsors, public.team_members, public.faqs, public.testimonials, public.site_blocks restart identity cascade;
select s.id, t.id, 1, 'ai-unlocked', 'AI Unlocked', 'Foundations of Artificial Intelligence', 'What AI really is, what it isn''t, and the map of the field you''re about to climb.', 'The first step clears the fog. We separate AI from the hype, trace how search, learning and reasoning fit together, and build an intuition for how a machine turns data into decisions. You''ll leave with a mental map of the whole stairway and your first tiny model running in the browser.', '2026-08-29T09:30:00+05:30', '2026-08-29T16:30:00+05:30', 'Main Seminar Hall, Block A', 'Beginner', array['Talk','Workshop']::text[], '[{"time":"09:30","title":"Check-in & coffee","detail":"Grab your badge, find a seat, connect to Wi-Fi."},{"time":"10:00","title":"Keynote: The AI landscape in 2026"},{"time":"11:30","title":"Short break"},{"time":"11:45","title":"Guided walkthrough","detail":"Live coding with the speaker — follow along on your laptop."},{"time":"13:00","title":"Lunch"},{"time":"14:00","title":"Build-your-first-model challenge","detail":"Work in pairs. Mentors float between tables."},{"time":"16:00","title":"Show & tell","detail":"Three teams demo what they built."},{"time":"16:30","title":"Wrap-up & next step preview"}]'::jsonb, array['Explain the difference between AI, ML and deep learning without buzzwords','Describe how a model learns from examples','Train a simple image classifier with Teachable Machine','Plan your personal route through the series']::text[], array['None. Really — just show up.']::text[], array['Laptop or phone','Charger','A notebook for the big-picture map']::text[], 120, 0, 'qr', 'MAIN-01', 'published', false, '{"slides":"https://example.com/stairway/step-01-slides.pdf","code":"https://github.com/ieeesbcek/stairway-step-01","recording":"https://www.youtube.com/embed/dQw4w9WgXcQ","reading":[{"label":"Elements of AI (free course)","href":"https://www.elementsofai.com/"}]}'::jsonb, '[]'::jsonb
from public.societies s left join public.tracks t on t.society_id = s.id and t.name = 'AI × Research & Innovation' where s.slug = 'main';
select s.id, t.id, 2, 'python-for-ai', 'Python for AI', 'NumPy, Pandas & Data Thinking', 'Arrays, dataframes and the habit of asking good questions of messy data.', 'Every model starts as a spreadsheet nobody wants to clean. This lab gets you fluent in the Python tools AI engineers use daily — NumPy for numbers, Pandas for tables, Matplotlib for seeing — and trains the instinct to spot what''s wrong with a dataset before it bites you.', '2026-09-05T09:30:00+05:30', '2026-09-05T16:30:00+05:30', 'Main Seminar Hall, Block A', 'Beginner', array['Lab']::text[], '[{"time":"09:30","title":"Check-in & coffee","detail":"Grab your badge, find a seat, connect to Wi-Fi."},{"time":"10:00","title":"Data thinking: questions before code"},{"time":"11:30","title":"Short break"},{"time":"11:45","title":"Guided walkthrough","detail":"Live coding with the speaker — follow along on your laptop."},{"time":"13:00","title":"Lunch"},{"time":"14:00","title":"Kerala rainfall dataset deep-dive","detail":"Work in pairs. Mentors float between tables."},{"time":"16:00","title":"Show & tell","detail":"Three teams demo what they built."},{"time":"16:30","title":"Wrap-up & next step preview"}]'::jsonb, array['Manipulate arrays and dataframes confidently','Clean a real-world dataset with missing and messy values','Plot distributions and correlations to find a story','Set up a reusable Colab workflow']::text[], array['Basic Python (variables, loops, functions)']::text[], array['Laptop (8 GB RAM recommended) and charger','Python 3.11+ installed','A Google account for Colab','Curiosity — plenty of it']::text[], 80, 0, 'qr', 'MAIN-02', 'published', false, '{"slides":"https://example.com/stairway/step-02-slides.pdf","notebook":"https://colab.research.google.com/","code":"https://github.com/ieeesbcek/stairway-step-02","recording":"https://www.youtube.com/embed/dQw4w9WgXcQ"}'::jsonb, '[]'::jsonb
from public.societies s left join public.tracks t on t.society_id = s.id and t.name = 'AI × Data Analytics' where s.slug = 'main';
select s.id, t.id, 3, 'ml-from-scratch', 'Machine Learning from Scratch', 'Regression to Classification', 'Write gradient descent by hand, then let scikit-learn do it a thousand times faster.', 'No black boxes on this step. You''ll implement linear and logistic regression from first principles, watch the loss curve fall, then graduate to scikit-learn pipelines, cross-validation and the metrics that actually matter when a model goes to production.', '2026-09-19T09:30:00+05:30', '2026-09-19T16:30:00+05:30', 'Main Seminar Hall, Block A', 'Intermediate', array['Workshop']::text[], '[{"time":"09:30","title":"Check-in & coffee","detail":"Grab your badge, find a seat, connect to Wi-Fi."},{"time":"10:00","title":"Learning = minimising a loss"},{"time":"11:30","title":"Short break"},{"time":"11:45","title":"Guided walkthrough","detail":"Live coding with the speaker — follow along on your laptop."},{"time":"13:00","title":"Lunch"},{"time":"14:00","title":"Predict KSRTC bus delays challenge","detail":"Work in pairs. Mentors float between tables."},{"time":"16:00","title":"Show & tell","detail":"Three teams demo what they built."},{"time":"16:30","title":"Wrap-up & next step preview"}]'::jsonb, array['Implement gradient descent in NumPy','Train and evaluate regression and classification models','Choose between accuracy, precision, recall and F1','Avoid data leakage with proper train/test splits']::text[], array['Step 02 or comfortable with NumPy & Pandas','High-school algebra']::text[], array['Laptop (8 GB RAM recommended) and charger','Python 3.11+ installed','A Google account for Colab','Curiosity — plenty of it']::text[], 80, 0, 'qr', 'MAIN-03', 'published', false, '{"slides":"https://example.com/stairway/step-03-slides.pdf","notebook":"https://colab.research.google.com/","code":"https://github.com/ieeesbcek/stairway-step-03","recording":"https://www.youtube.com/embed/dQw4w9WgXcQ"}'::jsonb, '[{"place":"1st","team":"Gradient Gang","project":"Bus delay predictor (MAE 3.2 min)"},{"place":"2nd","team":"Overfit Club","project":"Feature-engineered random forest"}]'::jsonb
from public.societies s left join public.tracks t on t.society_id = s.id and t.name = 'AI × Data Analytics' where s.slug = 'main';
select s.id, t.id, 1, 'seeing-machines', 'Seeing Machines', 'Computer Vision with OpenCV & CNNs', 'Teach a camera to see: filters, edges, and a CNN that recognises what''s in front of it.', 'Pixels are just numbers — until you know what to do with them. Start with classic OpenCV (filters, edges, contours), then build and train a convolutional neural network that classifies images, and finish by running real-time object detection on your own webcam feed.', '2026-10-10T09:30:00+05:30', '2026-10-10T16:30:00+05:30', 'Main Seminar Hall, Block A', 'Intermediate', array['Lab']::text[], '[{"time":"09:30","title":"Check-in & coffee","detail":"Grab your badge, find a seat, connect to Wi-Fi."},{"time":"10:00","title":"How machines see: from pixels to features"},{"time":"11:30","title":"Short break"},{"time":"11:45","title":"Guided walkthrough","detail":"Live coding with the speaker — follow along on your laptop."},{"time":"13:00","title":"Lunch"},{"time":"14:00","title":"Build a real-time mask/no-mask detector","detail":"Work in pairs. Mentors float between tables."},{"time":"16:00","title":"Show & tell","detail":"Three teams demo what they built."},{"time":"16:30","title":"Wrap-up & next step preview"}]'::jsonb, array['Process images and video streams with OpenCV','Explain convolutions, pooling and feature maps visually','Train a CNN and use transfer learning with a pre-trained model','Run real-time object detection on a webcam']::text[], array['Step 03 or basic ML knowledge','Comfortable with Python']::text[], array['Laptop (8 GB RAM recommended) and charger','Python 3.11+ installed','A Google account for Colab','Curiosity — plenty of it','OpenCV installed (pip install opencv-python)','A working webcam']::text[], 60, 0, 'qr', 'RAS-01', 'published', false, '{}'::jsonb, '[]'::jsonb
from public.societies s left join public.tracks t on t.society_id = s.id and t.name = 'AI × Computer Vision' where s.slug = 'ras';
select s.id, t.id, 4, 'deep-learning-decoded', 'Deep Learning Decoded', 'Neural Networks with PyTorch', 'Tensors, autograd and training loops — build a neural network you actually understand.', 'Open the hood of deep learning. Build a multilayer network neuron by neuron, then rebuild it in PyTorch, learn to read a training curve like a doctor reads an ECG, and fix the classic failure modes: vanishing gradients, overfitting and learning rates gone wild.', '2026-10-24T09:30:00+05:30', '2026-10-24T16:30:00+05:30', 'Main Seminar Hall, Block A', 'Intermediate', array['Workshop']::text[], '[{"time":"09:30","title":"Check-in & coffee","detail":"Grab your badge, find a seat, connect to Wi-Fi."},{"time":"10:00","title":"Neurons, layers and the chain rule"},{"time":"11:30","title":"Short break"},{"time":"11:45","title":"Guided walkthrough","detail":"Live coding with the speaker — follow along on your laptop."},{"time":"13:00","title":"Lunch"},{"time":"14:00","title":"Handwritten Malayalam digit recogniser","detail":"Work in pairs. Mentors float between tables."},{"time":"16:00","title":"Show & tell","detail":"Three teams demo what they built."},{"time":"16:30","title":"Wrap-up & next step preview"}]'::jsonb, array['Write a PyTorch training loop from memory','Diagnose overfitting and underfitting from loss curves','Use regularisation, dropout and batch norm effectively','Train on a GPU in Colab']::text[], array['Step 03 or equivalent ML basics']::text[], array['Laptop (8 GB RAM recommended) and charger','Python 3.11+ installed','A Google account for Colab','Curiosity — plenty of it','PyTorch installed or Colab ready']::text[], 60, 0, 'qr', 'MAIN-04', 'published', false, '{}'::jsonb, '[]'::jsonb
from public.societies s left join public.tracks t on t.society_id = s.id and t.name = 'AI × Research & Innovation' where s.slug = 'main';
select s.id, t.id, 1, 'language-and-machines', 'Language & Machines', 'NLP and Transformers', 'From word counts to attention: how machines learned to read.', 'Trace the path from bag-of-words to embeddings to the transformer. You''ll visualise attention, fine-tune a small transformer for sentiment analysis on Malayalam–English code-mixed text, and understand why ''Attention Is All You Need'' changed everything.', '2026-11-07T09:30:00+05:30', '2026-11-07T16:30:00+05:30', 'Main Seminar Hall, Block A', 'Intermediate', array['Workshop']::text[], '[{"time":"09:30","title":"Check-in & coffee","detail":"Grab your badge, find a seat, connect to Wi-Fi."},{"time":"10:00","title":"From words to vectors to attention"},{"time":"11:30","title":"Short break"},{"time":"11:45","title":"Guided walkthrough","detail":"Live coding with the speaker — follow along on your laptop."},{"time":"13:00","title":"Lunch"},{"time":"14:00","title":"Code-mixed sentiment fine-tuning sprint","detail":"Work in pairs. Mentors float between tables."},{"time":"16:00","title":"Show & tell","detail":"Three teams demo what they built."},{"time":"16:30","title":"Wrap-up & next step preview"}]'::jsonb, array['Tokenise text and build word embeddings','Explain self-attention with a whiteboard sketch','Fine-tune a Hugging Face transformer','Evaluate an NLP model honestly']::text[], array['Step 05 recommended','PyTorch basics']::text[], array['Laptop (8 GB RAM recommended) and charger','Python 3.11+ installed','A Google account for Colab','Curiosity — plenty of it']::text[], 60, 0, 'qr', 'CS-01', 'published', false, '{}'::jsonb, '[]'::jsonb
from public.societies s left join public.tracks t on t.society_id = s.id and t.name = 'AI × Software Engineering' where s.slug = 'cs';
select s.id, t.id, 5, 'inside-llms', 'Inside LLMs', 'How ChatGPT-like Models Work', 'Pre-training, fine-tuning, RLHF and inference — the full life of a large language model.', 'What actually happens between your prompt and the reply? We follow a large language model from raw web text to a helpful assistant: tokenisers, pre-training, instruction tuning, preference optimisation, and the tricks that make inference fast. In the lab you''ll train a tiny GPT on Malayalam poetry.', '2026-11-21T09:30:00+05:30', '2026-11-21T16:30:00+05:30', 'Main Seminar Hall, Block A', 'Advanced', array['Talk','Lab']::text[], '[{"time":"09:30","title":"Check-in & coffee","detail":"Grab your badge, find a seat, connect to Wi-Fi."},{"time":"10:00","title":"The life of a large language model"},{"time":"11:30","title":"Short break"},{"time":"11:45","title":"Guided walkthrough","detail":"Live coding with the speaker — follow along on your laptop."},{"time":"13:00","title":"Lunch"},{"time":"14:00","title":"nanoGPT on Malayalam poetry","detail":"Work in pairs. Mentors float between tables."},{"time":"16:00","title":"Show & tell","detail":"Three teams demo what they built."},{"time":"16:30","title":"Wrap-up & next step preview"}]'::jsonb, array['Describe the LLM training pipeline end to end','Explain context windows, temperature and sampling','Train a character-level GPT from scratch','Reason about cost, latency and model size trade-offs']::text[], array['Step 06 or transformer basics']::text[], array['Laptop (8 GB RAM recommended) and charger','Python 3.11+ installed','A Google account for Colab','Curiosity — plenty of it','Colab with GPU runtime enabled']::text[], 60, 0, 'qr', 'MAIN-05', 'published', false, '{}'::jsonb, '[]'::jsonb
from public.societies s left join public.tracks t on t.society_id = s.id and t.name = 'AI × Generative Media' where s.slug = 'main';
select s.id, t.id, 2, 'prompt-engineering-agents', 'Prompt Engineering & AI Agents', 'Tools, memory and autonomous workflows', 'Turn a chatbot into a teammate: prompting patterns, tool use and agent loops.', 'Prompting is a skill, and agents are where it pays off. Learn structured prompting patterns, give a model tools to call, add retrieval so it knows your documents, and wire it all into an agent that completes a multi-step task — then learn how to evaluate it so it doesn''t quietly fail.', '2026-12-05T09:30:00+05:30', '2026-12-05T16:30:00+05:30', 'Main Seminar Hall, Block A', 'Intermediate', array['Hands-on']::text[], '[{"time":"09:30","title":"Check-in & coffee","detail":"Grab your badge, find a seat, connect to Wi-Fi."},{"time":"10:00","title":"Patterns that make prompts reliable"},{"time":"11:30","title":"Short break"},{"time":"11:45","title":"Guided walkthrough","detail":"Live coding with the speaker — follow along on your laptop."},{"time":"13:00","title":"Lunch"},{"time":"14:00","title":"Build a campus-help agent for CEK","detail":"Work in pairs. Mentors float between tables."},{"time":"16:00","title":"Show & tell","detail":"Three teams demo what they built."},{"time":"16:30","title":"Wrap-up & next step preview"}]'::jsonb, array['Write reliable prompts with examples and structure','Build a retrieval-augmented (RAG) assistant','Give an LLM tools and let it act','Evaluate and guard an agent''s outputs']::text[], array['Python basics','Any prior step helps']::text[], array['Laptop (8 GB RAM recommended) and charger','Python 3.11+ installed','A Google account for Colab','Curiosity — plenty of it','Free API key from your LLM provider of choice']::text[], 70, 0, 'qr', 'CS-02', 'published', false, '{}'::jsonb, '[]'::jsonb
from public.societies s left join public.tracks t on t.society_id = s.id and t.name = 'AI × Web Development' where s.slug = 'cs';
select s.id, t.id, 6, 'generative-ai', 'Generative AI', 'Images, Audio & Creativity', 'Diffusion models, voice synthesis and the craft of making machines create.', 'Explore how diffusion models paint, how neural audio models speak and sing, and how artists are using both. You''ll run Stable Diffusion locally, fine-tune it on a small style dataset, and compose a short multimedia piece — plus a frank discussion of copyright and consent.', '2027-01-09T09:30:00+05:30', '2027-01-09T16:30:00+05:30', 'Main Seminar Hall, Block A', 'Intermediate', array['Lab']::text[], '[{"time":"09:30","title":"Check-in & coffee","detail":"Grab your badge, find a seat, connect to Wi-Fi."},{"time":"10:00","title":"Noise to art: diffusion explained"},{"time":"11:30","title":"Short break"},{"time":"11:45","title":"Guided walkthrough","detail":"Live coding with the speaker — follow along on your laptop."},{"time":"13:00","title":"Lunch"},{"time":"14:00","title":"Kerala mural style LoRA challenge","detail":"Work in pairs. Mentors float between tables."},{"time":"16:00","title":"Show & tell","detail":"Three teams demo what they built."},{"time":"16:30","title":"Wrap-up & next step preview"}]'::jsonb, array['Explain how diffusion turns noise into images','Generate and control images with prompts and ControlNet','Fine-tune a small LoRA on a custom style','Discuss the ethics of generative media']::text[], array['Step 05 recommended']::text[], array['Laptop (8 GB RAM recommended) and charger','Python 3.11+ installed','A Google account for Colab','Curiosity — plenty of it','Headphones']::text[], 60, 0, 'qr', 'MAIN-06', 'published', false, '{}'::jsonb, '[]'::jsonb
from public.societies s left join public.tracks t on t.society_id = s.id and t.name = 'AI × Generative Media' where s.slug = 'main';
select s.id, t.id, 1, 'ai-on-the-edge', 'AI on the Edge', 'AI with Microcontrollers & IoT', 'Shrink a model until it fits on a ₹500 board — and make it listen, see and react.', 'AI doesn''t only live in data centres. In this hardware lab you''ll quantise a model with TensorFlow Lite Micro, deploy keyword spotting to an ESP32, and build a sensor-driven device that makes decisions without the cloud. Kits are provided; you keep what you build.', '2027-01-23T09:30:00+05:30', '2027-01-23T16:30:00+05:30', 'Main Seminar Hall, Block A', 'Advanced', array['Lab']::text[], '[{"time":"09:30","title":"Check-in & coffee","detail":"Grab your badge, find a seat, connect to Wi-Fi."},{"time":"10:00","title":"Tiny models, big impact"},{"time":"11:30","title":"Short break"},{"time":"11:45","title":"Guided walkthrough","detail":"Live coding with the speaker — follow along on your laptop."},{"time":"13:00","title":"Lunch"},{"time":"14:00","title":"Build a keyword-spotting smart switch","detail":"Work in pairs. Mentors float between tables."},{"time":"16:00","title":"Show & tell","detail":"Three teams demo what they built."},{"time":"16:30","title":"Wrap-up & next step preview"}]'::jsonb, array['Quantise and compress a neural network','Deploy a model to an ESP32 microcontroller','Build a voice- or sensor-triggered edge device','Measure latency, memory and power']::text[], array['Step 05','Basic electronics or Arduino exposure helps']::text[], array['Laptop (8 GB RAM recommended) and charger','Python 3.11+ installed','A Google account for Colab','Curiosity — plenty of it','Arduino IDE installed','USB-C / micro-USB cable']::text[], 40, 0, 'qr', 'IAS-01', 'published', false, '{}'::jsonb, '[]'::jsonb
from public.societies s left join public.tracks t on t.society_id = s.id and t.name = 'AI × Industrial Automation' where s.slug = 'ias';
select s.id, t.id, 7, 'responsible-ai', 'Responsible AI', 'Ethics, Bias & Safety', 'Who gets hurt when models go wrong — and how builders can do better.', 'A panel of researchers, an industry practitioner and a lawyer take on the hard questions: bias in datasets, explainability, deepfakes, safety evaluations and India''s evolving AI policy. Bring your questions — half the session is open floor.', '2027-02-06T10:00:00+05:30', '2027-02-06T15:30:00+05:30', 'Main Seminar Hall, Block A', 'All levels', array['Panel']::text[], '[{"time":"10:00","title":"Opening provocation"},{"time":"10:30","title":"Panel: Who is AI built for?"},{"time":"12:00","title":"Case-study breakouts"},{"time":"13:00","title":"Lunch"},{"time":"14:00","title":"Open floor Q&A"},{"time":"15:00","title":"Summit briefing for Step 12"}]'::jsonb, array['Spot common sources of bias in data and models','Apply a lightweight fairness checklist to your project','Understand the basics of AI safety evaluation','Discuss AI regulation in India and worldwide']::text[], array['None']::text[], array['Your questions','An open mind']::text[], 150, 0, 'qr', 'MAIN-07', 'published', false, '{}'::jsonb, '[]'::jsonb
from public.societies s left join public.tracks t on t.society_id = s.id and t.name = 'AI × Cybersecurity' where s.slug = 'main';
select s.id, t.id, 8, 'the-summit', 'THE SUMMIT', 'st(AI)rway 24-Hour AI Hackathon', '24 hours, one problem statement, every step you''ve climbed. Build something that matters.', 'The top of the stairway. Teams of 2–4 get 24 hours to build an AI solution for a real problem from Kerala''s healthcare, agriculture, transport or education sectors. Mentors on call all night, food that doesn''t stop, and a ₹1,00,000 prize pool for the teams that climb highest.', '2027-02-27T10:00:00+05:30', '2027-02-28T10:00:00+05:30', 'Main Seminar Hall, Block A', 'All levels', array['Hackathon','Competition']::text[], '[{"time":"Sat 10:00","title":"Opening ceremony & problem statements"},{"time":"Sat 11:00","title":"Hacking begins"},{"time":"Sat 18:00","title":"Mentor round 1"},{"time":"Sun 00:00","title":"Midnight check-in & surprise challenge"},{"time":"Sun 06:00","title":"Mentor round 2"},{"time":"Sun 10:00","title":"Code freeze, demos & judging"}]'::jsonb, array['Ship a working AI prototype in 24 hours','Pitch to a jury of industry and academic judges','Work in a team under real constraints','Earn the Summit Climber badge']::text[], array['Teams of 2–4','At least one prior step recommended']::text[], array['Laptop (8 GB RAM recommended) and charger','Python 3.11+ installed','A Google account for Colab','Curiosity — plenty of it','Extension board','Sleeping bag (optional, brave)','Your team']::text[], 200, 0, 'qr', 'MAIN-08', 'published', true, '{}'::jsonb, '[]'::jsonb
from public.societies s left join public.tracks t on t.society_id = s.id and t.name = 'AI × Research & Innovation' where s.slug = 'main';
select s.id, t.id, 1, 'wie-ai-healthtech', 'Code Her Way: AI in HealthTech', 'Medical data, diagnosis models and ethics', 'Build a small diagnostic model on open health data and learn where AI helps — and where it must not decide alone.', 'Start with how hospitals actually use AI today, then train a simple classifier on an open medical dataset and examine its mistakes. We close with the questions every health-AI builder must answer: consent, bias and accountability.', '2026-10-17T09:30:00+05:30', '2026-10-17T16:30:00+05:30', 'Main Seminar Hall, Block A', 'Beginner', array['Workshop']::text[], '[{"time":"09:30","title":"Check-in & coffee"},{"time":"10:00","title":"Talk: AI in Indian healthcare today"},{"time":"11:45","title":"Guided walkthrough"},{"time":"13:00","title":"Lunch"},{"time":"14:00","title":"Diagnose-with-data lab","detail":"Work in pairs. Mentors float between tables."},{"time":"16:00","title":"Show & tell and wrap-up"}]'::jsonb, array['Explain common uses of AI in healthcare','Train and evaluate a simple diagnostic classifier','Spot bias in a medical dataset','Apply a responsible-AI checklist to a health project']::text[], array['None — beginners welcome']::text[], array['Laptop and charger','A Google account for Colab']::text[], 60, 0, 'qr', 'WIE-01', 'published', false, '{}'::jsonb, '[]'::jsonb
from public.societies s left join public.tracks t on t.society_id = s.id and t.name = 'AI × HealthTech' where s.slug = 'wie';
select s.id, t.id, 2, 'wie-designing-ai-for-everyone', 'Designing AI for Everyone', 'Accessible, inclusive AI products', 'Make AI products that work for people the tutorials forget — accessibility, language and context.', 'Explore how voice assistants, captioning and recommendation systems fail different users, then redesign an AI feature with accessibility and local-language users in mind. Hands-on with speech and vision APIs.', '2026-10-31T09:30:00+05:30', '2026-10-31T16:30:00+05:30', 'Main Seminar Hall, Block A', 'Beginner', array['Workshop']::text[], '[{"time":"09:30","title":"Check-in & coffee"},{"time":"10:00","title":"Talk: Who does AI leave out?"},{"time":"11:45","title":"Guided walkthrough"},{"time":"13:00","title":"Lunch"},{"time":"14:00","title":"Redesign-an-AI-feature sprint","detail":"Work in pairs. Mentors float between tables."},{"time":"16:00","title":"Show & tell and wrap-up"}]'::jsonb, array['Audit an AI feature for accessibility gaps','Prototype an inclusive AI interaction','Use speech and vision APIs in a small demo']::text[], array['None']::text[], array['Laptop and charger']::text[], 60, 0, 'qr', 'WIE-02', 'published', false, '{}'::jsonb, '[]'::jsonb
