select s.id, t.id, 3, 'wie-ai-for-good', 'AI for Good: Social Impact Sprint', 'Solving local problems with AI', 'A one-day build sprint on real problems from Kottayam — water, transport, safety and education.', 'Teams of two to four pick a local problem statement, find data, and prototype an AI-assisted solution in a day. Mentors help scope; a jury picks three teams to present at the next WIE session.', '2026-11-14T09:30:00+05:30', '2026-11-14T17:00:00+05:30', 'Main Seminar Hall, Block A', 'Intermediate', array['Competition']::text[], '[{"time":"09:30","title":"Problem statements & team formation"},{"time":"10:30","title":"Build sprint begins"},{"time":"13:00","title":"Lunch + mentor round"},{"time":"15:30","title":"Demos"},{"time":"16:30","title":"Jury results"}]'::jsonb, array['Scope a social-impact problem for AI','Prototype a working demo in a day','Pitch the impact and limits of your solution']::text[], array['Basic Python','Teams of 2–4 (solo sign-ups get matched)']::text[], array['Laptop and charger','Your team']::text[], 80, 0, 'qr', 'WIE-03', 'published', false, '{}'::jsonb, '[]'::jsonb
