insert into public.speakers (slug, name, designation, organization, photo_url, bio, topic, links, sort_order) values ('anjali-nair', 'Anjali Nair', 'Senior ML Engineer', 'Nimbus Labs, Bengaluru', null, 'Anjali builds language models for Indic languages and has shipped NLP systems used by millions. A CEK alumna, she started her AI journey in this very seminar hall.', 'Foundations & NLP', '{"linkedin":"https://linkedin.com","x":"https://x.com"}'::jsonb, 0);
insert into public.speakers (slug, name, designation, organization, photo_url, bio, topic, links, sort_order) values ('rahul-varghese', 'Rahul Varghese', 'Data Scientist', 'Backwater Analytics, Kochi', null, 'Rahul turns messy public datasets into decisions for state agencies. He teaches Pandas like it''s a detective story.', 'Python for AI', '{"linkedin":"https://linkedin.com","website":"https://example.com"}'::jsonb, 1);
