insert into public.speakers (slug, name, designation, organization, photo_url, bio, topic, links, sort_order) values ('arjun-pillai', 'Arjun Pillai', 'Embedded AI Engineer', 'Edgeworks Robotics, Technopark', null, 'Arjun puts neural networks on microcontrollers for agricultural drones. He believes every model should fit on a ₹500 board.', 'Computer Vision & Edge AI', '{"linkedin":"https://linkedin.com","x":"https://x.com"}'::jsonb, 3);
