insert into public.faqs (question, answer, sort_order) values ('Who can participate?', 'Any student — any branch, any year, any college. Faculty and alumni are welcome too. If you''re curious about AI, you belong on the stairway.', 0);
insert into public.faqs (question, answer, sort_order) values ('Is st(AI)rway free? Is there a registration fee?', 'Most weekends are free for IEEE members and carry a small ₹100 fee for non-members to cover lunch and materials. The Summit hackathon has a ₹200 team fee. Fees are listed on each weekend''s page.', 1);
insert into public.faqs (question, answer, sort_order) values ('Do I need prior AI or coding knowledge?', 'Not for the early steps. Steps 01 and 02 assume nothing beyond basic Python curiosity. Later steps list their prerequisites clearly so you can decide where to jump in.', 2);
insert into public.faqs (question, answer, sort_order) values ('Can students from other colleges join?', 'Absolutely. Register like everyone else and bring your college ID on the day.', 3);
insert into public.faqs (question, answer, sort_order) values ('Do I need to be an IEEE member? Are there benefits for members?', 'No membership required. Members get free entry to most weekends, priority seats when a step is full, and IEEE-verified certificates.', 4);
insert into public.faqs (question, answer, sort_order) values ('Do I need to attend every weekend?', 'No — each step stands on its own. But attending consecutive weekends earns streak badges, and the climb is more fun when you keep going.', 5);
insert into public.faqs (question, answer, sort_order) values ('What should I bring?', 'A laptop with charger, Python installed, and a Google account for Colab. Each weekend page lists any extra software or hardware.', 6);
insert into public.faqs (question, answer, sort_order) values ('Will I get a certificate?', 'Yes. Every step you attend earns a participation certificate from IEEE SB CEK. Winners and Summit finishers receive merit certificates.', 7);
insert into public.faqs (question, answer, sort_order) values ('Will sessions be recorded?', 'Talks are recorded and posted to the Resources hub within a week. Hands-on labs are best experienced live.', 8);
insert into public.faqs (question, answer, sort_order) values ('Are sessions online, offline, or hybrid?', 'Offline first, at the College of Engineering Kidangoor. Selected talks are live-streamed on our YouTube channel.', 9);
insert into public.faqs (question, answer, sort_order) values ('How do I join the community group?', 'Hit the WhatsApp button in the community section below. It''s where we post announcements, resources and memes.', 10);
insert into public.faqs (question, answer, sort_order) values ('How can I become a speaker, volunteer, or sponsor?', 'Speakers can apply through the speaker card in the Speakers section, volunteers through the community section, and sponsors can download our deck or email the sponsorship team.', 11);
insert into public.testimonials (quote, name, detail, step_label, photo_url, sort_order) values ('I walked in not knowing what a tensor was. By lunch I had trained my first model. By evening I''d signed up for every remaining step.', 'Akhil Sabu', 'S3 · Electronics', 'Step 01 — AI Unlocked', null, 0);
insert into public.testimonials (quote, name, detail, step_label, photo_url, sort_order) values ('The Pandas lab was the first time data cleaning felt like solving a mystery instead of a chore.', 'Riya Benny', 'S5 · Computer Science', 'Step 02 — Python for AI', null, 1);
insert into public.testimonials (quote, name, detail, step_label, photo_url, sort_order) values ('Writing gradient descent by hand finally made the maths click. Our team won the bus-delay challenge!', 'Sreehari K.', 'S7 · Computer Science', 'Step 03 — ML from Scratch', null, 2);
insert into public.testimonials (quote, name, detail, step_label, photo_url, sort_order) values ('Mentors actually sat with us and debugged. It felt less like an event and more like a lab with friends.', 'Neha Philip', 'S5 · Electrical', 'Step 03 — ML from Scratch', null, 3);
insert into public.testimonials (quote, name, detail, step_label, photo_url, sort_order) values ('I came from a mechanical background and nobody made me feel out of place. The stairway really does start at the bottom.', 'Arun Das', 'S3 · Mechanical', 'Step 01 — AI Unlocked', null, 4);
insert into public.testimonials (quote, name, detail, step_label, photo_url, sort_order) values ('Professional, well-paced and genuinely fun. I''ve been to paid bootcamps that were less organised.', 'Merin Jose', 'Alumna · 2024', 'Step 02 — Python for AI', null, 5);
